mapper.update:
update inventory_item
actual_location = #{actualLocation}, item_status = #{itemStatus}, deal_status = #{dealStatus}, deal_type = #{dealType}, deal_remark = #{dealRemark}, deal_user_id = #{dealUserId}, deal_user = #{dealUser}, deal_time = #{dealTime}, scanner_id = #{scannerId}, scanner_name = #{scannerName}, scan_time = #{scanTime}, comment = #{comment}, update_time = NOW()
where id = #{id}

mapper.select:
select from inventory_item
task_id = #{taskId}
AND item_status = #{itemStatus}
AND (assets_no LIKE CONCAT('%', #{keyword}, '%') OR assets_name LIKE CONCAT('%', #{keyword}, '%'))
order by is_extra asc, id asc
